#!/usr/bin/env python3
"""Compare a distance run's errors.tsv with the landed per-site list, by site.

Each location FILE:LINE of the run in an edited file is mapped back to the base
through `git diff -U0 BASE -- FILE`; a line inside a changed hunk maps to
FILE:+NEW (no base line).  The multisets of (kind, mapped location, message)
are compared, and the rows gone and new are printed with their per-site row.

usage: bysite.py BASE SITES.tsv ERRORS.tsv
"""
import collections, re, subprocess, sys

base, sites_path, errors_path = sys.argv[1:4]
FILES = {'FortressLibrary.fss': 'Library/FortressLibrary.fss',
         'FortressLibrary.fsi': 'Library/FortressLibrary.fsi'}

def hunks(path):
    out = subprocess.run(['git', 'diff', '-U0', base, '--', path], capture_output=True, text=True).stdout
    hs = []
    for m in re.finditer(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@', out, re.M):
        a, b, c, d = int(m.group(1)), int(m.group(2) or 1), int(m.group(3)), int(m.group(4) or 1)
        hs.append((a, b, c, d))
    return hs

H = {name: hunks(path) for name, path in FILES.items()}

def back(name, line):
    shift = 0
    for a, b, c, d in H[name]:
        start_new = c if d > 0 else c + 1
        if d > 0 and c <= line < c + d:
            return None
        if line >= start_new:
            shift = (c + d) - (a + b)
        else:
            break
    return line - shift

def map_loc(loc):
    parts = []
    for one in loc.split(','):
        m = re.match(r'(.*?)([A-Za-z0-9]+\.fs[si]):(\d+)$', one.strip())
        if m and m.group(2) in FILES:
            b = back(m.group(2), int(m.group(3)))
            parts.append('%s:%s' % (m.group(2), b if b is not None else '+%s' % m.group(3)))
        else:
            parts.append(one.strip())
    return ','.join(parts)

def norm_msg(msg):
    # line numbers inside messages of the edited files are mapped too
    def sub(m):
        name, line = m.group(1), int(m.group(2))
        b = back(name, line)
        return '%s:%s' % (name, b if b is not None else '+%d' % line)
    return re.sub(r'(FortressLibrary\.fs[si]):(\d+)', sub, msg)

def read(path, mapped):
    rows = []
    for n, line in enumerate(open(path), 1):
        if line.startswith('#') or not line.strip():
            continue
        cells = line.rstrip('\n').split('\t')
        kind, loc, msg = cells[0], cells[5], cells[6]
        if mapped:
            loc, msg = map_loc(loc), norm_msg(msg)
        rows.append((n, kind, loc, msg))
    return rows

def key(r):
    # the message with its embedded positions and paths stripped of columns
    msg = re.sub(r'/[^ ]*/', '', r[3])
    msg = re.sub(r':\d+(-\d+)?(:\d+(-\d+)?)?', '', msg)
    msg = re.sub(r'\.\d+\b', '', msg)
    return (r[1], re.sub(r'(\.fs[si]):(\d+)', r'\1:\2', r[2]), msg[:300])

sites = read(sites_path, False)
errs = read(errors_path, True)
cs = collections.Counter(key(r) for r in sites)
ce = collections.Counter(key(r) for r in errs)
gone = cs - ce
new = ce - cs
print('per-site list rows: %d; run rows: %d' % (len(sites), len(errs)))
