print('NEW (%d):' % sum(new.values()))
for r in errs:
    k = key(r)
    if new[k] > 0:
        new[k] -= 1
        print('  run:%d\t%s\t%s\t%s' % (r[0], r[1], r[2], r[3][:220]))

